/* eslint-disable react-hooks/exhaustive-deps */
import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import axios from 'axios';
import Logo from '../assets/logo.png';
// css link
import '../styles/auth.css';
import { registerRoute } from '../utils/APIRoutes';

// Function
function Register() {
  const navigate = useNavigate();
  // State
  const [values, setValues] = useState({
    username: '',
    mobileNumber: '',
    password: '',
    confirmPassword: '',
  });
  const [errorMsg, setErrorMsg] = useState({
    status: false,
    text: '',
  });
  useEffect(() => {
    if (localStorage.getItem('chaxapp-xchat')) navigate('/');
  }, []);

  // Handle Submit
  const handleSubmit = async (e) => {
    e.preventDefault();
    if (handleValidation()) {
      const { password, username, mobileNumber } = values;
      const { data } = await axios.post(registerRoute, {
        username,
        mobileNumber,
        password,
      });
      if (data.status === false) displayError(data.element, data.msg);
      if (data.status === true) {
        localStorage.setItem('chaxapp-xchat', JSON.stringify(data.user));
        navigate('/');
      }
    }
  };
  // HandleValidation
  function handleValidation() {
    const { password, username, mobileNumber, confirmPassword } = values;
    // Username
    if (username.length < 3)
      return displayError('username should contain minimum 3 characters');
    if (username.length > 19)
      return displayError('username should contain maximum 19 characters');
    // Mobile Number
    if (mobileNumber.length !== 10)
      return displayError('mobile number must have 10 digits');
    if (/[a-zA-Z]/g.test(mobileNumber))
      return displayError('mobile number should be digits');
    // Password
    if (password.length < 8)
      return displayError('password should contain minimum 8 characters');
    if (password.length > 12)
      return displayError('password should contain maximum 12 characters');
    // Confirm Password
    if (password !== confirmPassword)
      return displayError(`password and confirmPassword doesn't match`);
    return true;
  }
  // Display Error
  function displayError(text) {
    setErrorMsg({ status: true, text });
    return false;
  }
  // Handle Change
  const handleChange = (e) => {
    setValues({ ...values, [e.target.name]: e.target.value });
  };

  // Return
  return (
    <div id="register_component">
      <form onSubmit={(e) => handleSubmit(e)}>
        {/* Logo and title */}
        <div className="logo">
          <img src={Logo} alt="Brand Logo" />
          <h2>chaxapp</h2>
        </div>
        {/* Heading */}
        <div className="heading">
          <h3>Join us</h3>
        </div>
        {/* User div */}
        <div className="input_div">
          <input
            type="text"
            name="username"
            placeholder=" "
            onChange={(e) => handleChange(e)}
          />
          <label>username</label>
        </div>
        {/* Mobile number div */}
        <div className="input_div">
          <input
            type="text"
            name="mobileNumber"
            placeholder=" "
            onChange={(e) => handleChange(e)}
          />
          <label>Mobile number</label>
        </div>
        {/* Password div */}
        <div className="input_div">
          <input
            type="password"
            name="password"
            placeholder=" "
            onChange={(e) => handleChange(e)}
          />
          <label>Password</label>
        </div>
        {/* Confirm Password div */}
        <div className="input_div">
          <input
            type="password"
            name="confirmPassword"
            placeholder=" "
            onChange={(e) => handleChange(e)}
          />
          <label>Confirm Password</label>
        </div>
        {/* Error Div */}
        {errorMsg.status && <div className="errorDiv"> {errorMsg.text} </div>}
        {/* Register buttom */}
        <button type="submit">Create account</button>
        {/* hrd */}
        <div className="or">
          <span></span>
          <p>or</p>
          <span></span>
        </div>
        {/* login */}
        <div className="login_div">
          <p>Already have an account ?</p>
          <Link className=".link" to="/login">
            sign in
          </Link>
        </div>
      </form>
    </div>
  );
}

export default Register;
